import org.apache.maven.model.Resource;
import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;

/**
 * Minimal drop-in replacement for maven-resources-plugin's "resources" goal:
 * copies project resources to the main output directory.
 */
public class ResourcesMojo extends AbstractMojo {

    private File outputDirectory;
    private List<Resource> resources;
    private String encoding;
    private boolean overwrite;
    private boolean includeEmptyDirs;
    private boolean escapeWindowsPaths;
    private boolean useDefaultDelimiters;
    private List<String> delimiters;
    private List<String> nonFilteredFileExtensions;
    private String propertiesEncoding;
    private boolean fileNameFiltering;
    private boolean supportMultiLineFiltering;
    private List<String> filters;
    private boolean skip;

    @Override
    public void execute() throws MojoExecutionException {
        copyResources(resources, outputDirectory, skip, getLog()::info);
    }

    static void copyResources(List<Resource> resources, File outputDirectory, boolean skip,
                              java.util.function.Consumer<CharSequence> log) throws MojoExecutionException {
        if (skip) {
            log.accept("Skipping resource copying.");
            return;
        }
        if (resources == null || resources.isEmpty()) {
            return;
        }
        for (Resource resource : resources) {
            if (resource == null || resource.getDirectory() == null) {
                continue;
            }
            File sourceDir = new File(resource.getDirectory());
            if (!sourceDir.isDirectory()) {
                continue;
            }
            File targetDir = outputDirectory;
            if (resource.getTargetPath() != null && !resource.getTargetPath().isEmpty()) {
                targetDir = new File(outputDirectory, resource.getTargetPath());
            }
            copyTree(sourceDir.toPath(), targetDir.toPath());
        }
    }

    private static void copyTree(Path source, Path target) throws MojoExecutionException {
        try {
            copyRecursively(source, target);
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to copy resources from " + source + " to " + target, e);
        }
    }

    private static void copyRecursively(Path source, Path target) throws IOException {
        if (Files.isDirectory(source)) {
            Files.createDirectories(target);
            try (java.util.stream.Stream<Path> entries = Files.list(source)) {
                for (Path child : (Iterable<Path>) entries::iterator) {
                    copyRecursively(child, target.resolve(child.getFileName().toString()));
                }
            }
        } else {
            Files.createDirectories(target.getParent());
            Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.COPY_ATTRIBUTES);
        }
    }
}
