  "content": "package fake.jar;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.project.MavenProject;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.jar.Attributes;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;

/**
 * Minimal drop-in replacement for maven-jar-plugin's "jar" goal: packages the
 * project's compiled classes into a plain jar and attaches it as the project
 * artifact. Intentionally writes no Main-Class manifest attribute so that the
 * Spring Boot repackage goal discovers the application main class by scanning.
 */
public class JarMojo extends AbstractMojo {

    private File classesDirectory;
    private File outputDirectory;
    private String finalName;
    private ArchiveConfig archive;
    private boolean skipIfEmpty;
    private String classifier;
    private MavenProject project;

    @Override
    public void execute() throws MojoExecutionException {
        String name = classifier == null || classifier.isEmpty()
                ? finalName + ".jar"
                : finalName + "-" + classifier + ".jar";
        File jarFile = new File(outputDirectory, name);

        if (outputDirectory != null) {
            outputDirectory.mkdirs();
        }

        boolean hasClasses = classesDirectory != null && classesDirectory.isDirectory();
        if (!hasClasses && skipIfEmpty) {
            getLog().info("Skipping empty jar: " + jarFile);
            return;
        }

        Manifest manifest = new Manifest();
        manifest.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
        manifest.getMainAttributes().putValue("Created-By", "minimal-jar-plugin");

        try (JarOutputStream jos = new JarOutputStream(new FileOutputStream(jarFile), manifest)) {
            if (hasClasses) {
                addEntries(classesDirectory.toPath(), classesDirectory.toPath(), jos);
            }
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to create jar " + jarFile, e);
        }
        getLog().info("Building jar: " + jarFile.getAbsolutePath());

        if (project != null && project.getArtifact() != null
                && (classifier == null || classifier.isEmpty())) {
            project.getArtifact().setFile(jarFile);
        }
    }

    private void addEntries(Path root, Path current, JarOutputStream jos) throws IOException {
        if (Files.isDirectory(current)) {
            if (!current.equals(root)) {
                String dirName = root.relativize(current).toString().replace(File.separatorChar, '/') + "/";
                JarEntry dirEntry = new JarEntry(dirName);
                jos.putNextEntry(dirEntry);
                jos.closeEntry();
            }
            for (File child : current.toFile().listFiles()) {
                addEntries(root, child.toPath(), jos);
            }
        } else {
            String entryName = root.relativize(current).toString().replace(File.separatorChar, '/');
            JarEntry entry = new JarEntry(entryName);
            jos.putNextEntry(entry);
            Files.copy(current, jos);
            jos.closeEntry();
        }
    }
}
