import xml.etree.ElementTree as ET, os, re

REPO = "/root/.m2/repository"
NS = "{http://maven.apache.org/POM/4.0.0}"

def parse_pom(path):
    try:
        return ET.parse(path).getroot()
    except Exception:
        return None

def get_props(root):
    props = {}
    el = root.find(f"{NS}properties")
    if el is not None:
        for c in el:
            props[c.tag.replace(NS,'')] = (c.text or '').strip()
    # also groupId/version/artifactId resolvable
    gid = root.find(f"{NS}groupId")
    vid = root.find(f"{NS}version")
    parent = root.find(f"{NS}parent")
    if gid is not None: props['project.groupId'] = gid.text.strip(); props['pom.groupId'] = gid.text.strip()
    if vid is not None: props['project.version'] = vid.text.strip(); props['pom.version'] = vid.text.strip()
    if parent is not None:
        pg = parent.find(f"{NS}groupId").text.strip(); pv = parent.find(f"{NS}version").text.strip()
        props.setdefault('project.groupId', pg); props.setdefault('project.version', pv)
        props.setdefault('pom.groupId', pg); props.setdefault('pom.version', pv)
        props['parent.version'] = pv; props['project.parent.version'] = pv
    return props

def resolve(text, props, depth=0):
    if text is None or depth > 5: return text
    def sub(m):
        return props.get(m.group(1), m.group(0))
    return re.sub(r'\$\{([^}]+)\}', sub, text.strip())

def deps_of(g, a, v, seen):
    key = (g,a,v)
    if key in seen: return []
    seen.add(key)
    path = f"{REPO}/{g.replace('.','/')}/{a}/{v}/{a}-{v}.pom"
    if not os.path.exists(path):
        return [(g, a, v, "POM MISSING")]
    root = parse_pom(path)
    if root is None: return [(g,a,v,"POM PARSE FAIL")]
    props = get_props(root)
    missing = []
    deps = root.find(f"{NS}dependencies")
    if deps is not None:
        for d in deps.findall(f"{NS}dependency"):
            dg = d.find(f"{NS}groupId").text.strip()
            da = d.find(f"{NS}artifactId").text.strip()
            dv = d.find(f"{NS}version")
            dv = resolve(dv.text, props) if dv is not None else None
            scope = d.find(f"{NS}scope")
            scope = scope.text.strip() if scope is not None else "compile"
            optional = d.find(f"{NS}optional")
            optional = optional.text.strip() == "true" if optional is not None else False
            if scope in ("test", "provided", "system", "import") or optional:
                continue
            if dv is None or "${" in dv:
                continue  # managed elsewhere; skip
            jar = f"{REPO}/{dg.replace('.','/')}/{da}/{dv}/{da}-{dv}.jar"
            if not os.path.exists(jar):
                missing.append((dg, da, dv, "JAR MISSING"))
            missing += deps_of(dg, da, dv, seen)
    return missing

for g,a,v in [("org.springframework.boot","spring-boot-maven-plugin","3.2.5")]:
    seen=set()
    res = deps_of(g,a,v,seen)
    print(f"== {a} {v}: {'OK' if not res else ''}")
    for m in res[:40]: print("  ", m)
