import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;

import javax.tools.Diagnostic;
import javax.tools.DiagnosticCollector;
import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;
import java.io.File;
import java.io.IOException;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Shared compilation logic for the minimal compiler plugin: compiles all
 * .java sources under a source directory to an output directory using the
 * JDK's javax.tools.JavaCompiler.
 */
public abstract class AbstractCompileMojo extends AbstractMojo {

    protected String source;
    protected String target;
    protected String release;
    protected String encoding;
    protected boolean parameters;
    protected boolean debug;
    protected boolean skip;
    protected boolean skipMain;
    protected String proc;
    protected List<String> compilerArgs;
    protected List<String> classpathElements;

    protected abstract File getSourceDirectory();

    protected abstract File getOutputDirectory();

    protected abstract String getSkipPropertyValue();

    @Override
    public void execute() throws MojoExecutionException {
        if (skip || "true".equalsIgnoreCase(getSkipPropertyValue())) {
            getLog().info("Compilation is skipped.");
            return;
        }
        File sourceDir = getSourceDirectory();
        if (sourceDir == null || !sourceDir.isDirectory()) {
            getLog().info("No sources to compile (" + sourceDir + ")");
            return;
        }
        List<File> sources = new ArrayList<>();
        collectSources(sourceDir.toPath(), sources);
        if (sources.isEmpty()) {
            getLog().info("No sources to compile");
            return;
        }

        File outDir = getOutputDirectory();
        outDir.mkdirs();

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoExecutionException("No system Java compiler available (JDK required)");
        }

        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        Charset charset = encoding == null || encoding.isEmpty()
                ? Charset.defaultCharset() : Charset.forName(encoding);

        List<String> options = new ArrayList<>();
        options.add("-d");
        options.add(outDir.getAbsolutePath());
        options.add("-encoding");
        options.add(encoding == null ? "UTF-8" : encoding);
        if (classpathElements != null && !classpathElements.isEmpty()) {
            options.add("-classpath");
            options.add(String.join(File.pathSeparator, classpathElements));
        }
        if (release != null && !release.isEmpty()) {
            options.add("--release");
            options.add(release.trim());
        } else {
            if (source != null && !source.isEmpty()) {
                options.add("-source");
                options.add(source.trim());
            }
            if (target != null && !target.isEmpty()) {
                options.add("-target");
                options.add(target.trim());
            }
        }
        if (parameters) {
            options.add("-parameters");
        }
        if (proc != null) {
            options.add("-proc:" + proc.trim());
        }
        if (compilerArgs != null) {
            options.addAll(compilerArgs);
        }

        try (StandardJavaFileManager fileManager =
                     compiler.getStandardFileManager(diagnostics, null, charset)) {
            Iterable<? extends JavaFileObject> units = fileManager.getJavaFileObjectsFromFiles(sources);
            getLog().info("Compiling " + sources.size() + " source file(s) to " + outDir);
            boolean success = compiler.getTask(null, fileManager, diagnostics, options, null, units).call();
            if (!success) {
                StringBuilder message = new StringBuilder("Compilation failure:");
                for (Diagnostic<? extends JavaFileObject> diagnostic : diagnostics.getDiagnostics()) {
                    if (diagnostic.getKind() == Diagnostic.Kind.ERROR) {
                        message.append(System.lineSeparator()).append(diagnostic);
                    }
                }
                throw new MojoExecutionException(message.toString());
            }
            for (Diagnostic<? extends JavaFileObject> diagnostic : diagnostics.getDiagnostics()) {
                if (diagnostic.getKind() == Diagnostic.Kind.ERROR
                        || diagnostic.getKind() == Diagnostic.Kind.MANDATORY_WARNING
                        || diagnostic.getKind() == Diagnostic.Kind.WARNING) {
                    getLog().warn(String.valueOf(diagnostic));
                }
            }
        } catch (IOException e) {
            throw new MojoExecutionException("Compilation I/O failure", e);
        }
    }

    private void collectSources(Path dir, List<File> into) throws MojoExecutionException {
        File[] children = dir.toFile().listFiles();
        if (children == null) {
            return;
        }
        for (File child : children) {
            if (child.isDirectory()) {
                collectSources(child.toPath(), into);
            } else if (child.getName().endsWith(".java")) {
                into.add(child);
            }
        }
    }
}
